// Генерация случайной нормали в конусе вокруг данной нормали n
vec3 rvec(vec3 n, float k, vec3 p) {
    // Случайное направление в конусе
    float phi = 2.0 * 3.14159 * rand(p); // Случайный угол по кругу
    float cosTheta = cos(k * 3.14159 / 180.0); // косинус максимального угла
    float sinTheta = sin(k * 3.14159 / 180.0); // синус максимального угла
    float r = sinTheta * sqrt(rand(p)); // случайный радиус в пределах конуса

    // Вектор случайного направления
    vec3 randomDirection;
    randomDirection.x = r * cos(phi);
    randomDirection.y = r * sin(phi);
    randomDirection.z = sqrt(1.0 - dot(randomDirection.xyz, randomDirection.xyz));

    // Создание ортонормированного базиса от нормали n
    vec3 up = abs(n.z) < 0.999 ? vec3(0.0, 0.0, 1.0) : vec3(1.0, 0.0, 0.0);
    vec3 v1 = normalize(cross(up, n));
    vec3 v2 = cross(n, v1);

    // Преобразование случайного направления в основе нормали n
    return normalize(randomDirection.x * v1 + randomDirection.y * v2 + randomDirection.z * n);
}

mat3 rot(vec3 axis, float angle)
{
    axis = normalize(axis);
    float s = sin(angle);
    float c = cos(angle);
    float oc = 1.0 - c;

    return mat3(oc * axis.x * axis.x + c,           oc * axis.x * axis.y - axis.z * s,  oc * axis.z * axis.x + axis.y * s,
                oc * axis.x * axis.y + axis.z * s,  oc * axis.y * axis.y + c,           oc * axis.y * axis.z - axis.x * s,
                oc * axis.z * axis.x - axis.y * s,  oc * axis.y * axis.z + axis.x * s,  oc * axis.z * axis.z + c);
}

vec3 shade( vec3 p, vec3 n, vec3 v )
{
    //n = rvec(n, 5., 20. * p);

    vec3 lp = vec3(10., 10., -5.);//vec3(10. * sin(2. * iTime) - 8., 0, 10. * cos(2. * iTime) - 8.);
    vec3 l = -normalize(p - lp);
    float k = dot(l, n);
    vec3 color = 0.5 * vec3(0.5, 1. + sin(p.y), 1. + sin(p.x));
    vec3 r = reflect(normalize(v), n);

    vec3 diff = vec3(1) * pow(max(dot(r, l), 0.), 52.);
    //return n;
    //return texture(iChannel0, r).rgb;
    return k * color + diff + texture(iChannel0, r).rgb; 
}

float smin( float a, float b, float k )
{
    k *= 1.0;
    float r = exp2(-a/k) + exp2(-b/k);
    return -k*log2(r);
}


const vec3 C = vec3(0, 0, 7.2);

float cube( vec3 p, vec3 b )
{
  vec2 muv = C.z / 0.6 * (iMouse.xy - iResolution.xy / 2.) / max(iResolution.x, iResolution.y);
  vec3 c = vec3(muv, C.z);//vec3(5. * sin(iTime), 2. * sin(iTime / 3.), 10.);
  p = rot(vec3(1), iTime) * rot(vec3(0,1,0), 3. * iTime) * (p - c);
  vec3 q = abs(p) - b;
  return length(max(q,0.0)) + min(max(q.x,max(q.y,q.z)),0.0);
}


float sphere( vec3 p )
{
    //float fft = texture(iChannel2, vec2((2. + sin(p.x / 20.) + sin(p.y / 20.)) / 4., 0.25)).x;
    //float wave =  texture(iChannel2, vec2((2. + sin(p.x / 20.) + sin(p.y / 20.)) / 4., 0.75)).x;
    float sound1 = 2000. * pow(texture(iChannel2, vec2(512 / 3, 0)).x, 4.);
    float sound2 = 2000. * pow(texture(iChannel2, vec2(512 * 2 / 3, 0)).x, 4.);

    const vec3 c = C;
    p = rot(vec3(0,1,0), -iTime) * (p - c) + c;
    float r = 0.06 * (sound1 * pow(sin(2. * p.x + iTime),2.) + sound2 * pow(cos(2. * p.y + iTime),2.)) + 1.4f;
    return length(p - c) - r;
}

float ball( vec3 p )
{
    vec3 c = vec3(5. * sin(iTime), 3. * sin(iTime / 3.), 10.);
    float r = 0.5f;
    return length(p - c) - r;
}

float scene( vec3 p )
{
    const vec3 c = vec3(0, 0, 4.);
   // p = (rot(vec3(0,1,0), iTime) * vec4(p - c, 1)).xyz;
    return smin(cube(p, vec3(0.4)), sphere(p), .4);
}

vec3 grad( vec3 p )
{
    vec3 d = vec3(0.01, 0, 0);

    float dfx = scene(p + d.xyy) - scene(p);
    float dfy = scene(p + d.yxy) - scene(p);
    float dfz = scene(p + d.yyx) - scene(p);
    return normalize(vec3(dfx, dfy, dfz));
}

vec3 RayMarch( vec3 ro, vec3 rd ) 
{
    const float DELTA     = 0.01;
    const float FAR       = 240.f;
    const int STEPS = 1000;
    float d = 0.f;

    for (int i = 0; i < STEPS; i++)
    {
        vec3 p = ro + rd * d;
        float sdf = scene(p);
        vec3 n = grad(p);

        if (sdf < DELTA)
            return shade(p, n, rd);
        if (sdf > FAR || d > FAR)
            return texture(iChannel0, rd).xyz;//vec3(0.); 

        d += sdf;
    }
    return texture(iChannel0, rd).xyz;//vec3(0.);
}

